import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n], from = new int[n], to = new int[n];
        int maxId = 0;
        for (int i = 0; i < n; i++) maxId = Math.max(maxId, a[i] = nextInt());
        for (int i = 0; i < n; i++) maxId = Math.max(maxId, from[i] = nextInt());
        for (int i = 0; i < n; i++) maxId = Math.max(maxId, to[i] = nextInt());
        // Only the count of servers per ID matters.
        long[] freq = new long[maxId + 1];
        long total = 0;
        for (int v : a) {
            freq[v]++;
            total += v;
        }
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < n; j++) {
            int r = from[j], v = to[j];
            if (r != v) {
                long c = freq[r];
                freq[r] = 0;
                total += (long) (v - r) * c;
                freq[v] += c;
            }
            if (j > 0) out.append(' ');
            out.append(total);
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	read := func() []int64 {
		s := make([]int64, n)
		for i := range s {
			s[i] = nextInt()
		}
		return s
	}
	a, from, to := read(), read(), read()
	maxID := max(slices.Max(a), slices.Max(from), slices.Max(to))
	// Only the count of servers per ID matters.
	freq := make([]int64, maxID+1)
	var total int64
	for _, v := range a {
		freq[v]++
		total += v
	}
	out := make([]byte, 0, 12*n)
	for j := 0; j < n; j++ {
		r, v := from[j], to[j]
		if r != v {
			c := freq[r]
			freq[r] = 0
			total += (v - r) * c
			freq[v] += c
		}
		if j > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, total, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
